select 'date' as dimension, coalesce(r.value, f.value) as value from (select date::text as value, sum(impressions::numeric) as impressions, sum(clicks::numeric) as clicks, sum(conversions::numeric) as conversions, sum(ad_spend::numeric) as ad_spend, sum(revenue::numeric) as revenue from {{ source('raw', 'global_ads_performance') }} group by date) r full join (select d."Date"::text as value, sum(f."Impressions") as impressions, sum(f."Clicks") as clicks, sum(f."Conversions") as conversions, sum(f."AdSpend") as ad_spend, sum(f."Revenue") as revenue from {{ ref('fct_ad_performance') }} f join {{ ref('dim_date') }} d on d."DateKey" = f."DateKey" group by d."Date") f using (value) where r.value is null or f.value is null or r.impressions is distinct from f.impressions or r.clicks is distinct from f.clicks or r.conversions is distinct from f.conversions or r.ad_spend is distinct from f.ad_spend or r.revenue is distinct from f.revenue or r.clicks / nullif(r.impressions, 0) is distinct from f.clicks / nullif(f.impressions, 0) or r.ad_spend / nullif(r.clicks, 0) is distinct from f.ad_spend / nullif(f.clicks, 0) or r.ad_spend / nullif(r.conversions, 0) is distinct from f.ad_spend / nullif(f.conversions, 0) or r.conversions / nullif(r.clicks, 0) is distinct from f.conversions / nullif(f.clicks, 0) or r.revenue / nullif(r.ad_spend, 0) is distinct from f.revenue / nullif(f.ad_spend, 0)
union all
